# -*- coding: utf-8 -*-
"""Сборка пояснительной записки по шаблону преподавателя."""
import docx
from docx.shared import Pt, Cm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_TAB_ALIGNMENT, WD_BREAK
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

FONT = "Times New Roman"
SIZE = Pt(14)
INDENT = Cm(1.25)
TEXT_W = Cm(16.5)

OUT = "../Пояснительная_записка.docx"
doc = docx.Document()

# --- параметры страницы ---
s = doc.sections[0]
s.page_width, s.page_height = Cm(21), Cm(29.7)
s.left_margin, s.right_margin = Cm(3), Cm(1.5)
s.top_margin, s.bottom_margin = Cm(2), Cm(2)

# --- стиль по умолчанию ---
st = doc.styles["Normal"]
st.font.name = FONT
st.font.size = SIZE
st.element.rPr.rFonts.set(qn("w:eastAsia"), FONT)
st.element.rPr.rFonts.set(qn("w:cs"), FONT)
pf = st.paragraph_format
pf.line_spacing = 1.5
pf.space_after = Pt(0)
pf.space_before = Pt(0)


def style_run(r, bold=False, italic=False, size=SIZE):
    r.font.name = FONT
    r.font.size = size
    r.bold = bold
    r.italic = italic
    r.font.color.rgb = RGBColor(0, 0, 0)
    rf = r._element.get_or_add_rPr().get_or_add_rFonts()
    rf.set(qn("w:eastAsia"), FONT)
    rf.set(qn("w:cs"), FONT)
    return r


def par(text="", align="just", indent=True, bold=False, size=SIZE, space_before=0):
    p = doc.add_paragraph()
    f = p.paragraph_format
    f.alignment = {"just": WD_ALIGN_PARAGRAPH.JUSTIFY,
                   "center": WD_ALIGN_PARAGRAPH.CENTER,
                   "left": WD_ALIGN_PARAGRAPH.LEFT}[align]
    f.line_spacing = 1.5
    f.space_after = Pt(0)
    f.space_before = Pt(space_before)
    f.first_line_indent = INDENT if indent else Cm(0)
    if text:
        style_run(p.add_run(text), bold=bold, size=size)
    return p


def heading(text, new_page=False):
    p = par(text, align="just", indent=True)
    if new_page:
        p.paragraph_format.page_break_before = True
    return p


def picture(path, width_cm, caption):
    p = doc.add_paragraph()
    p.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = Cm(0)
    p.paragraph_format.line_spacing = 1.0
    p.paragraph_format.space_before = Pt(6)
    p.paragraph_format.space_after = Pt(0)
    p.add_run().add_picture(path, width=Cm(width_cm))
    c = par(caption, align="center", indent=False)
    c.paragraph_format.line_spacing = 1.0
    c.paragraph_format.space_after = Pt(6)
    return c


def formula(parts, number):
    """parts — список (текст, режим): '' обычный, 'sup' верхний, 'sub' нижний индекс."""
    p = doc.add_paragraph()
    f = p.paragraph_format
    f.alignment = WD_ALIGN_PARAGRAPH.LEFT
    f.first_line_indent = Cm(0)
    f.line_spacing = 1.5
    f.space_before = Pt(6)
    f.space_after = Pt(6)
    f.tab_stops.add_tab_stop(Cm(8.25), WD_TAB_ALIGNMENT.CENTER)
    f.tab_stops.add_tab_stop(TEXT_W, WD_TAB_ALIGNMENT.RIGHT)
    style_run(p.add_run("\t"))
    for text, mode in parts:
        r = style_run(p.add_run(text))
        if mode == "sup":
            r.font.superscript = True
        elif mode == "sub":
            r.font.subscript = True
    style_run(p.add_run("\t" + number))
    return p


def keep_with_next(paragraph):
    """Запретить отрыв абзаца от следующего — таблица не разорвётся по страницам."""
    pPr = paragraph._p.get_or_add_pPr()
    pPr.append(OxmlElement("w:keepNext"))


def keep_table_together(table, caption):
    """Держать подпись и всю таблицу на одной странице."""
    keep_with_next(caption)
    last = table.rows[-1]
    for row in table.rows:
        trPr = row._tr.get_or_add_trPr()
        trPr.append(OxmlElement("w:cantSplit"))
        if row is last:
            continue
        for cell in row.cells:
            for p in cell.paragraphs:
                keep_with_next(p)


def set_cell(cell, text, bold=False, align=WD_ALIGN_PARAGRAPH.LEFT):
    cell.text = ""
    p = cell.paragraphs[0]
    p.paragraph_format.alignment = align
    p.paragraph_format.line_spacing = 1.0
    p.paragraph_format.space_before = Pt(2)
    p.paragraph_format.space_after = Pt(2)
    p.paragraph_format.first_line_indent = Cm(0)
    style_run(p.add_run(text), bold=bold, size=Pt(12))




